<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Foundry\SubordinateConstructionCaseService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:foundry:open-subordinate-construction-cases',description:'Open one exact Foundry construction case per authorized subordinate resolution')]
final class FoundryOpenSubordinateConstructionCasesCommand extends Command{public function __construct(private readonly SubordinateConstructionCaseService $service){parent::__construct();}protected function configure():void{$this->addArgument('acceptance-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface $input,OutputInterface $output):int{try{$r=$this->service->open((string)$input->getArgument('acceptance-id'));}catch(\Throwable$e){$output->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$input->getOption('json')){$output->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$output->writeln('<info>SUBORDINATE_CONSTRUCTION_CASES_OPENED</info> '.count($r['cases']));$output->writeln('Artificer: '.$r['artificer']['manifestation_id']);foreach($r['cases']as$c)$output->writeln('- '.$c['queue_position'].' '.$c['office'].' '.$c['subordinate_staff_class'].' '.$c['case_id'].' '.$c['status']);$output->writeln('Persona selection authority: NOT GRANTED');$output->writeln('Profile approval authority: NOT GRANTED');$output->writeln('Spawning authority: NOT GRANTED');$output->writeln('Admission authority: NOT GRANTED');$output->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
